    [Xunit.Fact]
    public static void TestNeverAndOfflineWinOverEveryHook() {
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchNever(), 0, 1, Adapters.PdecFetch()), Adapters.PactUnread(), "never: a fetch answer is not honoured");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchNever(), 0, 1, Adapters.PdecProvide()), Adapters.PactUnread(), "never: nor a provide");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchNever(), 0, 1, Adapters.PdecSubstitute()), Adapters.PactUnread(), "never: nor a substitute");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchNever(), 0, 0, 0), Adapters.PactUnread(), "never with no hook: unread");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchAuto(), 1, 1, Adapters.PdecFetch()), Adapters.PactUnread(), "EMON_OFFLINE=1 in auto: unread");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchAuto(), 1, 0, 0), Adapters.PactUnread(), "EMON_OFFLINE=1 with no hook: unread");
        emon.Testport.AssertEq(Adapters.AdPackAction(0, Engines.PfetchCache(), 1, 1, Adapters.PdecProvide()), Adapters.PactUnread(), "EMON_OFFLINE=1 in cache: unread");
        emon.Testport.AssertEq(Adapters.AdAsksHook(0, Engines.PfetchNever(), 0, 1), 0, "the hook is not even asked under never");
        emon.Testport.AssertEq(Adapters.AdAsksHook(0, Engines.PfetchAuto(), 1, 1), 0, "nor offline");
    }
